async function load(url,name){generation++;worker?.terminate();const id=generation,im=new Image();await new Promise((ok,bad)=>{im.onload=ok;im.onerror=()=>bad(new Error('Не удалось открыть изображение.'));im.src=url;});if(id!==generation)return;if(im.width*im.height>30e6||im.width/im.height<.35||im.width/im.height>3)throw new Error('Нужна картинка до 30 Мп, пропорции от 1:3 до 3:1.');const scale=Math.min(1,720/Math.max(im.width,im.height));iw=Math.round(im.width*scale);ih=Math.round(im.height*scale);sourceCanvas.width=iw;sourceCanvas.height=ih;const ctx=sourceCanvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#000';ctx.fillRect(0,0,iw,ih);ctx.drawImage(im,0,0,iw,ih);gray=rgbaToGray(ctx.getImageData(0,0,iw,ih).data,iw,ih).gray;$('original').src=sourceCanvas.toDataURL('image/png');imageName=name;calculate();}
function calculate(mode='normal'){clearTimeout(timer);worker?.terminate();generation++;const id=generation;searching=mode==='search';quality=null;search=null;setBusy(true,searching?'Подбираем физически допустимую схему…':'Строим маску и корпус…');for(const k of fields)if(!$(k).checkValidity()){error('Проверьте параметр '+k);return;}if(!gray)return;timer=setTimeout(()=>{worker=new Worker('projector-worker.mjs?v=projector-4',{type:'module'});worker.onmessage=({data})=>{if(id!==generation)return;if(data.phase==='error'){error(data.message);return;}if(data.phase==='progress'){$('busyText').textContent=data.label||`Проверено ${data.checked} из ${data.total} вариантов`;$('searchStatus').textContent=$('busyText').textContent;return;}if(data.phase==='geometry'){design=data.d;return;}design=data.d;sim=data.sim;quality=data.quality;search=data.search||null;settings={...design.p};settings.exposureEV=Math.round(autoExposure({data:sim.data},settings.ambient)*10)/10;settings.exposureEV=Math.max(-2,Math.min(6,settings.exposureEV));design.p.exposureEV=settings.exposureEV;searching=false;sync();setBusy(false);paint();metrics();if(model)model.dirty=true;if(view==='model')void updateModel();$('searchStatus').textContent=search?`Проверено ${search.checked} вариантов. ${quality.accepted?'Финалист прошёл цифровые критерии.':'Ни один выбранный результат пока не подтверждён.'} Абсолютный оптимум не гарантируется.`:'Результат проверен по исходной ч/б цели и полной области стены.';};worker.onerror=e=>error(e.message);worker.postMessage({gray,iw,ih,settings,mode});},120);}
