function pixelMM(x,y){return[((x+.5)/sim.width-.5)*sim.worldWidth+sim.centerX,(.5-(y+.5)/sim.height)*sim.worldHeight+sim.centerY];}
function paint(){if(!sim)return;lightCanvas.width=sim.width;lightCanvas.height=sim.height;const ctx=lightCanvas.getContext('2d'),im=ctx.createImageData(sim.width,sim.height);for(let k=0;k<sim.data.length;k++){const rgb=displayRGB(sim.data[k],settings.ambient,settings.exposureEV);for(let j=0;j<3;j++)im.data[k*4+j]=rgb[j];im.data[k*4+3]=255;}ctx.putImageData(im,0,0);const c=$('wallCanvas');c.width=sim.width*2;c.height=sim.height*2;const out=c.getContext('2d');out.drawImage(lightCanvas,0,0,c.width,c.height);const scale=c.width/sim.worldWidth,B=design.p.bodySide/2,x=(-B-sim.centerX+sim.worldWidth/2)*scale,y=(sim.worldHeight/2+sim.centerY-B)*scale,s=design.p.bodySide*scale;out.fillStyle='#182117';out.strokeStyle='#667658';out.lineWidth=1.4;out.fillRect(x,y,s,s);out.strokeRect(x,y,s,s);out.fillStyle='#b2b99d';out.font=`${Math.max(9,4*scale)}px Segoe UI`;out.textAlign='center';out.fillText('ОТКРЫТЫЙ КОРПУС',x+s/2,y+s*.27);out.fillStyle='#edbd72';out.beginPath();out.arc(x+s/2,y+s/2,4*scale,0,Math.PI*2);out.fill();out.font=`${Math.max(8,3.5*scale)}px Segoe UI`;out.fillStyle='#a5ae96';out.fillText('E10 · источник в центре',x+s/2,y+s*.77);paintCompare();if(model)model.texture.needsUpdate=true;}
function paintCompare(){if(!sim||!design)return;const d=design,r=d.ref;for(const id of ['targetCanvas','stencilCanvas','actualCanvas','errorCanvas']){const c=$(id);c.width=r.nx;c.height=r.ny;const ctx=c.getContext('2d'),im=ctx.createImageData(r.nx,r.ny);for(let y=0;y<r.ny;y++)for(let x=0;x<r.nx;x++){const k=y*r.nx+x,wx=(x+.5-r.nx/2)*d.pitch+d.q.imageX,wy=(r.ny/2-y-.5)*d.pitch+d.q.imageY,sx=Math.floor(((wx-sim.centerX)/sim.worldWidth+.5)*sim.width),sy=Math.floor((.5-(wy-sim.centerY)/sim.worldHeight)*sim.height),actual=sx>=0&&sy>=0&&sx<sim.width&&sy<sim.height?1-sim.visibility[sy*sim.width+sx]:1,mx=Math.floor((wx/d.q.magnification+d.p.bodySide/2)/d.maskGrid.pitch),my=Math.floor((d.p.bodySide/2-wy/d.q.magnification)/d.maskGrid.pitch),material=d.maskGrid.black[my*d.maskGrid.N+mx]||0;let rgb;if(id==='errorCanvas'){const e=Math.abs(actual-r.raw[k]);rgb=[20+e*235,31+e*30,20+e*10];}else{const v=255*(1-(id==='targetCanvas'?r.raw[k]:id==='stencilCanvas'?material:actual));rgb=[v,v,v];}for(let j=0;j<3;j++)im.data[k*4+j]=rgb[j];im.data[k*4+3]=255;}ctx.putImageData(im,0,0);}}
function metrics(){const d=design,q=quality;$('iou').textContent=fmt(q.iou*100)+'%';$('edges').textContent=fmt(q.edgeF1*100)+'%';$('leak').textContent=fmt(q.leakage*100,2)+'%';$('contrast').textContent=fmt(q.contrast*100)+'%';document.querySelector('.verdict').classList.toggle('good',q.accepted);$('verdict').textContent=q.accepted?'Цифровая проверка пройдена':'Нужна доработка — готовность не подтверждена';$('reasons').textContent=q.accepted?'Рисунок сравнивается с исходной целью. Паразитный свет проверяется за пределами окна. Это расчётный прототип, не результат физического испытания.':q.reasons.join('. ')+'. Попробуйте больший корпус, более крупные детали или другой референс.';$('opticsInfo').textContent=`Картина ${fmt(d.p.wallWidth,0)} × ${fmt(d.height,0)} мм, ${labels[d.q.layout]}. Увеличение ${fmt(d.q.magnification)}×. Стена → маска ${fmt(d.q.maskZ)} мм, маска → нить ${fmt(d.q.sourceGap)} мм. Полутень ≈ ${fmt(d.q.penumbra)} мм.`;$('partsInfo').textContent=`Корпус ${d.p.bodySide} × ${d.p.bodySide} мм. Маска ${d.p.thickness} мм; добавлено перемычек: ${d.bridges}. Проверяется ${d.triangles.length.toLocaleString('ru-RU')} треугольников, включая держатель, патрон и опоры.`;}
