async function updateModel(){if(!design||!sim||modelBusy)return;modelBusy=true;try{if(!model){const THREE=await import('three'),{OrbitControls}=await import('./vendor/OrbitControls.js'),host=$('modelView'),renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.prepend(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(42,1,1,2400);camera.position.set(330,220,490);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,30,90);controls.enableDamping=true;scene.add(new THREE.HemisphereLight(0xffedce,0x3b5030,2.6));const light=new THREE.DirectionalLight(0xfff0cd,3);light.position.set(200,250,400);scene.add(light);const group=new THREE.Group();scene.add(group);const texture=new THREE.CanvasTexture(lightCanvas);texture.colorSpace=THREE.SRGBColorSpace;model={THREE,host,renderer,scene,camera,controls,group,texture,dirty:true};new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;if(w&&h){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}}).observe(host);renderer.setAnimationLoop(()=>{if(view==='model'){controls.update();renderer.render(scene,camera);}});}
 if(!model.dirty)return;const{THREE,group}=model;const cx=sim.centerX*.7,cy=sim.centerY*.7,span=Math.max(sim.worldHeight,sim.worldWidth/(model.host.clientWidth/model.host.clientHeight||1.5)),distance=span/(2*Math.tan(model.camera.fov*Math.PI/360))*1.35;model.controls.target.set(cx,cy,70);model.camera.position.set(cx+distance*.5,cy+distance*.25,70+distance*.85);for(const c of [...group.children]){group.remove(c);c.geometry?.dispose();c.material?.dispose();}for(const p of [...design.parts,{name:'purchased-socket',triangles:design.socket}]){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(p.triangles.flat(),3));geometry.computeVertexNormals();const mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:p.name==='gobo-mask'?0x586d46:p.name==='purchased-socket'?0xa7ac99:0x283a23,roughness:.65,metalness:p.name==='purchased-socket'?.6:0}));mesh.name=p.name;group.add(mesh);}const bulb=new THREE.Mesh(new THREE.SphereGeometry(5.5,24,16),new THREE.MeshStandardMaterial({color:0xffdc93,emissive:0xf9ac3c,emissiveIntensity:.8,transparent:true,opacity:.75}));bulb.name='bulb';bulb.position.z=design.p.sourceZ;group.add(bulb);const neck=new THREE.Mesh(new THREE.CylinderGeometry(2.8,2.8,9,16),bulb.material.clone());neck.rotation.x=Math.PI/2;neck.position.z=design.p.sourceZ+6;group.add(neck);const wall=new THREE.Mesh(new THREE.PlaneGeometry(sim.worldWidth,sim.worldHeight),new THREE.MeshBasicMaterial({map:model.texture,side:THREE.DoubleSide}));wall.name='wall';wall.position.set(sim.centerX,sim.centerY,-1);group.add(wall);model.dirty=false;model.texture.needsUpdate=true;modelOptions();}catch(e){$('status').textContent='3D-просмотр: '+e.message;}finally{modelBusy=false;}}
