async function exportKit(){if(!quality?.accepted)return;const d={...design,p:{...design.p}},exportQuality=structuredClone(quality),exportSettings={...settings},exportSearch=search?structuredClone(search):null,exportName=imageName,exportImage=sourceCanvas.toDataURL('image/png');$('export').disabled=true;const exportCanvas=document.createElement('canvas');exportCanvas.width=$('wallCanvas').width;exportCanvas.height=$('wallCanvas').height;exportCanvas.getContext('2d').drawImage($('wallCanvas'),0,0);const parts=d.parts.map(p=>({...p,...normalize(p.triangles)})),png=await new Promise(r=>exportCanvas.toBlob(r,'image/png'));if(!png)throw new Error('Не удалось сохранить изображение.');const assembly={units:'mm',type:'square-gobo-projector',source:[0,0,d.p.sourceZ],maskZ:d.q.maskZ,projection:d.q,parts:parts.map(p=>({file:p.name+'.stl',position:[0,0,p.z]})),purchasedSocket:{z:[d.p.sourceZ+8,d.p.sourceZ+28],nominalDiameter:d.p.socket-2,measured:false}};const readme=`ShadowForge — квадратный гобо-проектор\n\nКартина: ${d.p.wallWidth} × ${d.height.toFixed(2)} мм, центр (${d.q.imageX}, ${d.q.imageY}). Стена z=0; нить (0,0,${d.p.sourceZ}). Маска z=${d.q.maskZ.toFixed(3)}, толщина${d.p.thickness}. Все STL опущены на стол; позиции для сборки в assembly.json.\n\nПЕЧАТЬ И СБОРКА\nМаска, квадратный кожух, поперечный держатель патрона и две стеновые стойки печатаются отдельно. Маска кладётся плоско, кожух открытым квадратным торцом на стол, держатель плоско, стойки основаниями на стол. После примерки маска клеится к заднему торцу кожуха, тонкий держатель — НА передний торец: детали касаются плоскостями, не пересекаются. Передняя сторона остаётся открытой. Стойки устанавливаются со стороны, противоположной проекции, и приклеиваются торцами к непрозрачной рамке маски. В каждой стеновой пятке два сквозных отверстияØ3.4; крепёж покупной, выбирается по стене. Перед постоянной фиксацией проверьте совмещение и источник.\n\nИСТОЧНИК\nПрозрачная E10 3.5V/0.2A/0.7W, покупной патрон. Отверстие держателя Ø${d.p.socket} мм — заготовка без резьбы. Нить должна оказаться на25мм за внутренней стороной держателя в направлении стены. Реальный патрон и положение нити ОБЯЗАТЕЛЬНО измерить. Не230V. Провода провести по стойке вне светового конуса и кожуху к патрону; в рисунок не заводить. Колба не должна касаться пластика.\n\nПРОВЕРКА\nТрассировка по всем треугольникам STL плюс номинальный непрозрачный патрон. Маска имеет реальные перемычки (${d.bridges}). Вырезы скошены по лучам, боковой кожух физически ограничивает поле. Нет программной обрезки светового пятна. IoU к исходной ч/б цели ${(exportQuality.iou*100).toFixed(2)}%; контуры ${(exportQuality.edgeF1*100).toFixed(2)}%; утечки ${(exportQuality.leakage*100).toFixed(4)}%.\n\nОГРАНИЧЕНИЯ\nЭто проверенный цифровой прототип. Физическая печать, нагрев, прочность и фотометрия не проверены. Номинальная перемычка ${d.p.minWeb} мм не является сертификатом минимальной толщины по каждому месту. Сначала распечатайте тестовую маску и проверьте её в слайсере. Световой поток E10 неизвестен, нужна тёмная комната. Стекло, отражения, просвечивание пластика и провода не моделируются. Нельзя оставлять включённым без теплового испытания.\n`;const files=[...parts.map(p=>[p.name+'.stl',stlBuffer(p.triangles)]),['assembly.json',JSON.stringify(assembly,null,2)],['validation.json',JSON.stringify({quality:exportQuality,limits:d.limits,search:exportSearch,settings:d.p,physicalValidation:false},null,2)],['project.json',JSON.stringify({format:'shadowforge-gobo',version:1,name:exportName,settings:exportSettings,image:exportImage},null,2)],['README.txt',readme],['wall-preview.png',await png.arrayBuffer()]];save(zipStore(files),'shadowforge-gobo-kit.zip');$('export').disabled=!quality?.accepted||!$('busy').hidden;}
for(const k of fields)$(k).addEventListener('input',()=>{settings[k]=+$(k).value;sync();if(k==='exposureEV'){if(design)design.p.exposureEV=settings.exposureEV;paint();return;}if(k==='ambient'&&sim){design.p.ambient=settings.ambient;quality=null;$('export').disabled=true;$('verdict').textContent='Засветка изменилась — пересчитайте';}calculate();});for(const k of ['layout','style'])$(k).addEventListener('change',()=>{settings[k]=$(k).value;calculate();});$('search').addEventListener('click',()=>{if(searching){calculate();return;}calculate('search');});$('autoEV').addEventListener('click',()=>{if(!sim)return;settings.exposureEV=Math.max(-2,Math.min(6,Math.round(autoExposure({data:sim.data},settings.ambient)*10)/10));sync();paint();});for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>void switchView(b.dataset.view));for(const k of ['showWall','explode'])$(k).addEventListener('change',modelOptions);$('export').addEventListener('click',()=>exportKit().catch(e=>error(e.message)));$('reference').addEventListener('change',()=>load('assets/references/'+$('reference').value,$('reference').selectedOptions[0].textContent).catch(e=>error(e.message)));$('imageFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>15e6){error('Изображение больше15МБ.');return;}const url=URL.createObjectURL(f);try{await load(url,f.name);}catch(err){error(err.message);}finally{URL.revokeObjectURL(url);e.target.value='';}});sync();load('assets/references/'+$('reference').value,imageName).catch(e=>error(e.message));
